import './styles.css';
import { useState } from 'react';

interface Neuron {
  value: number;
  preActivation: number;
  isActive: boolean;
}

const WEIGHTS = {
  layer1: [
    [0.6, -0.4],
    [0.3, 0.8],
    [-0.2, 0.5],
  ],
  layer2: [
    [0.7, -0.3, 0.4],
    [0.2, 0.6, -0.5],
  ],
  output: [
    [0.5, 0.4],
  ],
};

const BIASES = {
  layer1: [0.1, -0.1, 0.2],
  layer2: [0.15, -0.05],
  output: [0.1],
};

function relu(x: number): number {
  return Math.max(0, x);
}

function sigmoid(x: number): number {
  return 1 / (1 + Math.exp(-x));
}

function NeuronCircle({ 
  value, 
  preActivation,
  label, 
  type, 
  isActive,
  showDetails 
}: { 
  value: number; 
  preActivation?: number;
  label: string; 
  type: 'input' | 'hidden' | 'output';
  isActive: boolean;
  showDetails: boolean;
}) {
  return (
    <div className={`neuron-container ${isActive ? 'active' : ''}`}>
      <div className={`neuron-circle ${type}`}>
        <span className="neuron-value">{value.toFixed(2)}</span>
      </div>
      <span className="neuron-label">{label}</span>
      {showDetails && preActivation !== undefined && type !== 'input' && (
        <div className="neuron-detail">
          <span className="detail-pre">pre: {preActivation.toFixed(2)}</span>
          <span className="detail-arrow">→</span>
          <span className="detail-post">{value.toFixed(2)}</span>
        </div>
      )}
    </div>
  );
}

function WeightConnection({ 
  weight, 
  fromValue,
  isActive 
}: { 
  weight: number; 
  fromValue: number;
  isActive: boolean;
}) {
  const contribution = weight * fromValue;
  return (
    <div className={`weight-info ${isActive ? 'active' : ''}`}>
      <span className="weight-value">w={weight.toFixed(1)}</span>
      {isActive && (
        <span className="contribution">
          {fromValue.toFixed(2)} × {weight.toFixed(1)} = {contribution.toFixed(2)}
        </span>
      )}
    </div>
  );
}

export default function App() {
  const [inputs, setInputs] = useState([0.5, 0.8]);
  const [currentStep, setCurrentStep] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  // Calculate all layer values
  const calculateNetwork = () => {
    // Layer 1
    const layer1Pre = WEIGHTS.layer1.map((weights, i) => 
      weights.reduce((sum, w, j) => sum + w * inputs[j], 0) + BIASES.layer1[i]
    );
    const layer1 = layer1Pre.map(relu);

    // Layer 2
    const layer2Pre = WEIGHTS.layer2.map((weights, i) =>
      weights.reduce((sum, w, j) => sum + w * layer1[j], 0) + BIASES.layer2[i]
    );
    const layer2 = layer2Pre.map(relu);

    // Output
    const outputPre = WEIGHTS.output.map((weights, i) =>
      weights.reduce((sum, w, j) => sum + w * layer2[j], 0) + BIASES.output[i]
    );
    const output = outputPre.map(sigmoid);

    return { layer1, layer1Pre, layer2, layer2Pre, output, outputPre };
  };

  const network = calculateNetwork();
  const totalSteps = 4; // input, layer1, layer2, output

  const stepDescriptions = [
    'Input values enter the network',
    'Hidden Layer 1: Weighted sum + bias, then ReLU activation',
    'Hidden Layer 2: Weighted sum + bias, then ReLU activation',
    'Output Layer: Weighted sum + bias, then Sigmoid activation',
  ];

  const nextStep = () => {
    if (currentStep < totalSteps - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const reset = () => {
    setCurrentStep(0);
    setIsPlaying(false);
  };

  const playAll = () => {
    setIsPlaying(true);
    setCurrentStep(0);
    let step = 0;
    const interval = setInterval(() => {
      step++;
      if (step >= totalSteps) {
        clearInterval(interval);
        setIsPlaying(false);
      } else {
        setCurrentStep(step);
      }
    }, 1200);
  };

  return (
    <div className="app">
      <div className="header">
        <h1>Forward Pass Simulator</h1>
        <p className="subtitle">
          Watch data flow through a neural network, one layer at a time.
        </p>
      </div>

      <div className="input-controls">
        <h3>Input Values</h3>
        <div className="input-sliders">
          {inputs.map((val, i) => (
            <div key={i} className="slider-group">
              <label>x{i + 1}: {val.toFixed(2)}</label>
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={val}
                onChange={(e) => {
                  const newInputs = [...inputs];
                  newInputs[i] = parseFloat(e.target.value);
                  setInputs(newInputs);
                }}
              />
            </div>
          ))}
        </div>
      </div>

      <div className="network-display">
        <div className="layer-column">
          <h4>Input</h4>
          {inputs.map((val, i) => (
            <NeuronCircle
              key={i}
              value={val}
              label={`x${i + 1}`}
              type="input"
              isActive={currentStep >= 0}
              showDetails={false}
            />
          ))}
        </div>

        <div className="arrow-column">
          <div className={`flow-arrow ${currentStep >= 1 ? 'active' : ''}`}>→</div>
        </div>

        <div className="layer-column">
          <h4>Hidden 1</h4>
          {network.layer1.map((val, i) => (
            <NeuronCircle
              key={i}
              value={currentStep >= 1 ? val : 0}
              preActivation={network.layer1Pre[i]}
              label={`h1${i + 1}`}
              type="hidden"
              isActive={currentStep >= 1}
              showDetails={currentStep === 1}
            />
          ))}
        </div>

        <div className="arrow-column">
          <div className={`flow-arrow ${currentStep >= 2 ? 'active' : ''}`}>→</div>
        </div>

        <div className="layer-column">
          <h4>Hidden 2</h4>
          {network.layer2.map((val, i) => (
            <NeuronCircle
              key={i}
              value={currentStep >= 2 ? val : 0}
              preActivation={network.layer2Pre[i]}
              label={`h2${i + 1}`}
              type="hidden"
              isActive={currentStep >= 2}
              showDetails={currentStep === 2}
            />
          ))}
        </div>

        <div className="arrow-column">
          <div className={`flow-arrow ${currentStep >= 3 ? 'active' : ''}`}>→</div>
        </div>

        <div className="layer-column">
          <h4>Output</h4>
          {network.output.map((val, i) => (
            <NeuronCircle
              key={i}
              value={currentStep >= 3 ? val : 0}
              preActivation={network.outputPre[i]}
              label={`y${i + 1}`}
              type="output"
              isActive={currentStep >= 3}
              showDetails={currentStep === 3}
            />
          ))}
        </div>
      </div>

      <div className="step-info">
        <div className="step-indicator">
          Step {currentStep + 1} of {totalSteps}
        </div>
        <p className="step-description">{stepDescriptions[currentStep]}</p>
      </div>

      <div className="playback-controls">
        <button onClick={reset} className="btn" disabled={isPlaying}>
          Reset
        </button>
        <button onClick={prevStep} className="btn" disabled={currentStep === 0 || isPlaying}>
          ← Previous
        </button>
        <button onClick={playAll} className="btn play" disabled={isPlaying}>
          {isPlaying ? 'Playing...' : 'Play All'}
        </button>
        <button onClick={nextStep} className="btn" disabled={currentStep === totalSteps - 1 || isPlaying}>
          Next →
        </button>
      </div>

      <div className="insight-box">
        <h3>What's Happening</h3>
        <p>
          At each layer, every neuron computes: <code>activation(sum(inputs × weights) + bias)</code>
        </p>
        <p>
          <strong>ReLU</strong> (hidden layers): Outputs the value if positive, 0 otherwise.<br/>
          <strong>Sigmoid</strong> (output): Squishes any number to between 0 and 1.
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
