  background: linear-gradient(135deg, #0ea5e9 0%, #6366f1 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 900px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.95rem;
}

.input-controls {
  background: white;
  border-radius: 1rem;
  padding: 1rem 1.5rem;
  margin-bottom: 1rem;
}

.input-controls h3 {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 0.75rem;
}

.input-sliders {
  display: flex;
  gap: 2rem;
}

.slider-group {
  flex: 1;
}

.slider-group label {
  display: block;
  font-size: 0.85rem;
  color: #6b7280;
  margin-bottom: 0.5rem;
}

.slider-group input[type="range"] {
  width: 100%;
  accent-color: #6366f1;
}

.network-display {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  margin-bottom: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 0.5rem;
  overflow-x: auto;
}

.layer-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  min-width: 100px;
}

.layer-column h4 {
  font-size: 0.8rem;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.arrow-column {
  display: flex;
  align-items: center;
  padding-top: 2rem;
}

.flow-arrow {
  font-size: 1.5rem;
  color: #d1d5db;
  transition: all 0.3s;
}

.flow-arrow.active {
  color: #6366f1;
  animation: pulse 0.5s ease-out;
}

.neuron-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  transition: all 0.3s;
}

.neuron-container.active .neuron-circle {
  transform: scale(1.1);
}

.neuron-circle {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 3px solid;
  transition: all 0.3s;
}

.neuron-circle.input {
  background: #dbeafe;
  border-color: #3b82f6;
}

.neuron-circle.hidden {
  background: #f3e8ff;
  border-color: #8b5cf6;
}

.neuron-circle.output {
  background: #dcfce7;
  border-color: #22c55e;
}

.neuron-value {
  font-size: 0.85rem;
  font-weight: 600;
  color: #1f2937;
}

.neuron-label {
  font-size: 0.75rem;
  color: #9ca3af;
}

.neuron-detail {
  font-size: 0.65rem;
  color: #6b7280;
  background: #f3f4f6;
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.detail-arrow {
  color: #9ca3af;
}

.step-info {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1rem 1.5rem;
  margin-bottom: 1rem;
  text-align: center;
}

.step-indicator {
  font-size: 0.8rem;
  color: #6366f1;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.step-description {
  color: #374151;
  font-size: 0.95rem;
}

.playback-controls {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.btn {
  padding: 0.6rem 1.25rem;
  border: none;
  border-radius: 0.5rem;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  background: white;
  color: #374151;
  transition: all 0.2s;
}

.btn:hover:not(:disabled) {
  background: #f3f4f6;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn.play {
  background: #6366f1;
  color: white;
}

.btn.play:hover:not(:disabled) {
  background: #4f46e5;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.25rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.insight-box code {
  background: #f3f4f6;
  padding: 0.15rem 0.4rem;
  border-radius: 0.25rem;
  font-size: 0.85rem;
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.2); }
  100% { transform: scale(1); }
}

@media (max-width: 700px) {
  .network-display {
    padding: 1rem;
  }

  .neuron-circle {
    width: 50px;
    height: 50px;
  }

  .layer-column {
    min-width: 70px;
  }

  .playback-controls {
    flex-wrap: wrap;
  }
}
